AISummarizerAsyncWaiter::AISummarizerAsyncWaiter(
    AISummarizer* proxy) : proxy_(proxy) {}

AISummarizerAsyncWaiter::~AISummarizerAsyncWaiter() = default;


void AISummarizerAsyncWaiter::MeasureUsage(
    const ::blink::String& input, const ::blink::String& context, std::optional<uint32_t>* out_number_of_tokens) {
  base::RunLoop loop;
  proxy_->MeasureUsage(
      std::move(input),
      std::move(context),
      base::BindOnce(
          [](base::RunLoop* loop,
             std::optional<uint32_t>* out_number_of_tokens
,
             std::optional<uint32_t> number_of_tokens) {*out_number_of_tokens = std::move(number_of_tokens);
            loop->Quit();
          },
          &loop,
          out_number_of_tokens));
  loop.Run();
}

std::optional<uint32_t> AISummarizerAsyncWaiter::MeasureUsage(
    const ::blink::String& input, const ::blink::String& context) {
  std::optional<uint32_t> async_wait_result;
  MeasureUsage(std::move(input),std::move(context),&async_wait_result);
  return async_wait_result;
}






